    var result = Stream.concat(constraintMap.keySet().stream(),
            other.constraintMap.keySet().stream())
            .distinct()
            .flatMap(constraintRef -> {
                var constraintAnalysis = getConstraintAnalysis(constraintRef);
                var otherConstraintAnalysis = other.getConstraintAnalysis(constraintRef);
                var diff = ConstraintAnalysis.diff(constraintRef, constraintAnalysis, otherConstraintAnalysis);

                // Check for incompatible match data presence
                boolean hasMatches = diff.matches() != null && !diff.matches().isEmpty();
                boolean constraintHasMatches = constraintAnalysis != null && constraintAnalysis.matches() != null && !constraintAnalysis.matches().isEmpty();
                boolean otherHasMatches = otherConstraintAnalysis != null && otherConstraintAnalysis.matches() != null && !otherConstraintAnalysis.matches().isEmpty();

                if (constraintHasMatches != otherHasMatches) {
                    throw new IllegalStateException("Cannot diff ScoreAnalysis instances with incompatible match data for constraint: " + constraintRef);
                }

                // Exclude if both weight and score differences are zero
                if (diff.weight().isZero() && diff.score().isZero()) {
                    // Only include if there are meaningful match differences
                    if (hasMatches) {
                        return Stream.of(diff);
                    } else {
                        return Stream.empty();
                    }
                }

                return Stream.of(diff);
            })
            .collect(Collectors.toMap(
                    ConstraintAnalysis::constraintRef,
                    Function.identity(),
                    (existing, replacement) -> existing,
                    HashMap::new));
    return new ScoreAnalysis<>(score.subtract(other.score()), result, isSolutionInitialized);
}

