List<Document> get() {
    List<Paragraph> paragraphs = this.paragraphTextExtractor.getParagraphs();

    if (CollectionUtils.isEmpty(paragraphs)) {
        return new ArrayList<>();
    }

    List<Document> documents = new ArrayList<>();

    for (int i = 0; i < paragraphs.size(); i++) {
        Paragraph currentParagraph = paragraphs.get(i);
        Paragraph nextParagraph = (i < paragraphs.size() - 1) ? paragraphs.get(i + 1) : currentParagraph;

        String combinedText = currentParagraph.getText() + "\n" + nextParagraph.getText();

        Document document = new Document(combinedText);
        document.getMetadata().put(METADATA_START_PAGE, currentParagraph.getStartPage());
        document.getMetadata().put(METADATA_END_PAGE, nextParagraph.getEndPage());
        document.getMetadata().put(METADATA_TITLE, currentParagraph.getTitle());
        document.getMetadata().put(METADATA_LEVEL, currentParagraph.getLevel());

        if (StringUtils.hasText(this.resourceFileName)) {
            document.getMetadata().put(METADATA_FILE_NAME, this.resourceFileName);
        }

        documents.add(document);
    }

    return documents;
}

