public static String underlineToCamel(String string) {
    if (string == null || string.isEmpty()) {
        return string;
    }

    int strLen = string.length();
    StringBuilder sb = new StringBuilder(strLen);

    for (int i = 0; i < strLen; i++) {
        char c = string.charAt(i);
        if (c == '_') {
            // Skip underscore and capitalize next character if it exists and is not underscore
            if (i + 1 < strLen && string.charAt(i + 1) != '_') {
                i++; // Move to next character
                sb.append(Character.toUpperCase(string.charAt(i)));
            }
            // If underscore is at end or followed by another underscore, just skip it
        } else {
            // Convert first character to lowercase if it's uppercase
            if (i == 0 && Character.isUpperCase(c)) {
                sb.append(Character.toLowerCase(c));
            } else {
                sb.append(c);
            }
        }
    }
    return sb.toString();
}

